import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.DC2anBTf.js";const p=JSON.parse('{"title":"AI 辅助开发","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-collab.md","filePath":"guide/ai-collab.md","lastUpdated":1793536832000}'),o={name:"guide/ai-collab.md"};function l(c,t,i,s,n,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-辅助开发" tabindex="-1">AI 辅助开发 <a class="header-anchor" href="#ai-辅助开发" aria-label="Permalink to &quot;AI 辅助开发&quot;">​</a></h1><p>本模板将「AI 助手如何在此架构下工作」沉淀为可执行的规则与技能，存放在 <code>.trae/</code> 目录，与代码同库演进。</p><h2 id="组成" tabindex="-1">组成 <a class="header-anchor" href="#组成" aria-label="Permalink to &quot;组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>路径</th><th>职责</th></tr></thead><tbody><tr><td>架构开发规则</td><td><code>.trae/rules/architecture.md</code></td><td>架构规范的<strong>机器强制约束层</strong>：分层调用链与禁令、插件清单（导入路径唯一事实源）、标准落码顺序、类型组织判据、UTS 红线、装配点唯一、验证 DoD</td></tr><tr><td>AI 行为协议</td><td><code>.trae/rules/core-protocol.md</code></td><td>辩证执行、工作模式（交互 / 无人值守 / 谋定而后动）、DoD 检查清单、经验教训记录</td></tr><tr><td>文档驱动工作流</td><td><code>.trae/rules/workflow.md</code></td><td>功能实现强制流程：建立任务文档 → 等待并读取回答 → 实现与验证 → 实施记录回填，全程落盘跨会话持久</td></tr><tr><td>通用规范沉淀</td><td><code>.trae/rules/project_rules.md</code></td><td>uni-app x / UTS / uvue / ucss 通用约束摘录</td></tr><tr><td>新功能开发技能</td><td><code>.trae/skills/arch-feature/SKILL.md</code></td><td>六步落码：需求确认 → DTO → api → store → 页面/组件 → 装配点检查 → 验证闭环</td></tr><tr><td>任务文档归档</td><td><code>.trae/documents/</code></td><td>按「需求类型 / 日期」两级目录归档；<code>implementation-log.md</code> 为全项目任务索引</td></tr><tr><td>MCP 配置</td><td><code>.trae/mcp.json</code></td><td>uni-app-x MCP 服务器，供 AI 查询插件与 API 平台兼容性</td></tr></tbody></table><h2 id="设计原理" tabindex="-1">设计原理 <a class="header-anchor" href="#设计原理" aria-label="Permalink to &quot;设计原理&quot;">​</a></h2><ul><li><strong>原理层与强制层分离</strong>：仓库首页架构文档讲「为什么这样设计」，<code>.trae/rules/architecture.md</code> 讲「AI 必须怎么写」——二者同源、同步演进；</li><li><strong>红线不漂移</strong>：AI 生成代码时被规则约束在分层内，UTS 红线清单直接注入上下文，编译级踩坑在生成阶段就被拦住；</li><li><strong>文档驱动</strong>：需求分析、伪代码、疑问与回答全部落盘任务文档，跨会话循环推进，对话只做通知与执行。</li></ul><h2 id="实际收益" tabindex="-1">实际收益 <a class="header-anchor" href="#实际收益" aria-label="Permalink to &quot;实际收益&quot;">​</a></h2><p>最大的收益不是「写得快」，而是<strong>架构约定被机器执行</strong>：AI 不会为了「简洁」绕过分层，不会凭记忆写错插件导入路径，不会踩 UTS 红线清单里的坑——这些恰是人机协作中最容易失控的部分。</p>',8)])])}const m=e(o,[["render",l]]);export{p as __pageData,m as default};
